func _run_tests() -> void:
	var box_scene := await instantiate_scene("res://ui/dialogue_box.tscn")
	if not check("box_exists", box_scene != null, "La scena res://ui/dialogue_box.tscn deve caricarsi correttamente"):
		return

	var text_label := find_by_name(box_scene, "TextLabel") as RichTextLabel
	if not check("text_label", text_label != null, "DialogueBox deve contenere il nodo TextLabel"):
		return

	var start_time := Time.get_ticks_msec()
	box_scene.call("show_line", "Elena", "Alt! {wait=0.4} Chi va la?")
	await wait_frames(2)

	check("no_tag_visible", not text_label.text.contains("{wait="), "Il testo mostrato in TextLabel non deve contenere la stringa del tag {wait=...}")
	check("text_cleaned", text_label.text.contains("Alt!") and text_label.text.contains("Chi va la?"), "Il testo mostrato deve contenere la battuta visibile pulita")

	await wait_seconds(1.5)
	var elapsed := float(Time.get_ticks_msec() - start_time) / 1000.0
	check("pause_applied", elapsed >= 0.5, "La pausa di 0.4s specificata nel tag deve essere stata applicata durante la digitazione (misurati %.2f s)" % elapsed)

